test('hidden range deletes interpolated boxes, preserves other people, and survives undo, redo, export and reload',async({page,request})=>{
 await page.getByTestId('canvas').press('n');await drag(page,[100,80],[200,300]);await page.getByLabel('Go to frame').fill('20');await ready(page,20);await drag(page,[200,80],[300,300]);await saved(page);
 const who=Object.keys((await state(request)).state.identities)[0];
 await page.getByLabel('Go to frame').fill('10');await ready(page,10);await page.getByTestId('canvas').press('n');await drag(page,[350,80],[450,300]);await saved(page);await page.locator('.person').filter({hasText:'Track 1'}).click();
 const before=(await state(request)).state;
 await page.getByRole('button',{name:'Delete range',exact:true}).click();await page.getByLabel('First frame to delete').fill('8');await page.getByLabel('Last frame to delete').fill('12');await expect(page.getByRole('dialog')).toContainText('5 boxes');await page.getByRole('button',{name:'Cancel',exact:true}).click();expect((await state(request)).state).toEqual(before);
 await page.getByTestId('canvas').press('Shift+Delete');await page.getByLabel('First frame to delete').fill('8');await page.getByLabel('Last frame to delete').fill('12');await page.getByRole('button',{name:'Delete boxes',exact:true}).click();await saved(page);
 let p=await state(request);const gap=Object.values(p.state.intervals) as any[];expect(gap).toMatchObject([{identity_uuid:who,start:8,end:12}]);expect(obs(p).filter(o=>o.identity_uuid===who&&o.frame_index>=8&&o.frame_index<=12)).toHaveLength(0);expect(obs(p).filter(o=>o.identity_uuid!==who)).toHaveLength(1);await expect(page.locator('.gap-banner')).toContainText('Interpolation paused');
 await page.getByTestId('canvas').press('Control+z');await saved(page);expect((await state(request)).state).toEqual(before);await page.keyboard.press('Control+Shift+z');await saved(page);expect((await state(request)).state).toEqual(p.state);
 await page.getByRole('button',{name:'Go to frame 13',exact:true}).click();await ready(page,13);await drag(page,[215,190],[225,190]);await saved(page);await page.getByTestId('canvas').press('k');await saved(page);p=await state(request);expect(obs(p).filter(o=>o.identity_uuid===who&&o.frame_index>=8&&o.frame_index<=12)).toHaveLength(0);expect(obs(p).find(o=>o.identity_uuid===who&&o.frame_index===16)!.boxes?.['class:person_visible'][0]).toBeGreaterThan(180);
 await reopen(page);await ready(page,13);await page.getByLabel('Go to frame').fill('10');await ready(page,10);await expect(page.locator('.gap-banner')).toContainText('Interpolation paused');
 const exportId=await validatedExport(request);const exported=await (await request.get('/api/exports/'+exportId)).json();expect(Object.values(exported.state.intervals)).toMatchObject([{start:8,end:12,reason:'unknown'}]);expect(exported.presence_intervals.find((r:any)=>r.identity_uuid===who&&r.class_key==='class:person_visible'&&r.start===8)).toMatchObject({end:12,status:'absent',basis:'explicit_gap',reason:'unknown'});expect(exported.annotation_index.filter((o:any)=>o.identity_uuid===who&&o.frame_index>=8&&o.frame_index<=12)).toHaveLength(0);
});

test('restore deleted range preserves new endpoints, supports exact undo, and recovers originals in a fresh browser',async({page,request,browser})=>{
 await page.getByTestId('canvas').press('n');await drag(page,[100,80],[200,300]);await page.getByLabel('Go to frame').fill('20');await ready(page,20);await drag(page,[200,80],[300,300]);await saved(page);const original=(await state(request)).state;
 await page.getByTestId('canvas').press('Shift+Delete');await page.getByLabel('First frame to delete').fill('8');await page.getByLabel('Last frame to delete').fill('12');await page.getByRole('button',{name:'Delete boxes',exact:true}).click();await saved(page);
 await page.getByLabel('Go to frame').fill('8');await ready(page,8);await drag(page,[130,80],[230,300]);await page.getByLabel('Go to frame').fill('12');await ready(page,12);await drag(page,[190,80],[290,300]);await saved(page);const blocked=(await state(request)).state;expect(at({state:blocked},10)).toBeUndefined();
 await page.getByRole('button',{name:'Restore range',exact:true}).click();await page.getByLabel('First frame to restore').fill('8');await page.getByLabel('Last frame to restore').fill('12');await expect(page.getByRole('dialog')).toContainText('3 boxes to restore');await expect(page.getByRole('dialog')).toContainText('2 existing boxes kept');
 await page.route(`**/api/projects/${projectId}/operations`,route=>route.abort('failed'));await page.getByRole('radio',{name:/Recover deleted boxes/}).check();await expect(page.getByRole('dialog')).toContainText('Saved history could not be loaded');await expect(page.getByRole('button',{name:'Recover deleted boxes',exact:true})).toBeDisabled();await expect(page.locator('.restore-preview')).toHaveCount(0);expect((await state(request)).state).toEqual(blocked);
 await page.unroute(`**/api/projects/${projectId}/operations`);await page.getByRole('radio',{name:/Fill between my boxes/}).check();await page.getByRole('button',{name:'Remove gap & fill boxes',exact:true}).click();await saved(page);
 const restored=await state(request);expect(at(restored,10).boxes?.['class:person_visible'][0]).toBeCloseTo(160,0);expect(at(restored,8)).toEqual(at({state:blocked},8));expect(at(restored,12)).toEqual(at({state:blocked},12));expect(Object.values(restored.state.intervals)).toHaveLength(0);
 await page.getByTestId('canvas').press('Control+z');await saved(page);expect((await state(request)).state).toEqual(blocked);
 const fresh=await browser.newContext({baseURL:new URL(page.url()).origin,viewport:{width:1440,height:960}});
 let releaseHistory!:()=>void,requested=false;const waitingHistory=new Promise<void>(resolve=>{releaseHistory=resolve});await fresh.route(`**/api/projects/${projectId}/operations`,async route=>{requested=true;await waitingHistory;await route.continue()});
 try{
  const other=await fresh.newPage();await other.goto('/');await other.getByTestId('open-project-'+projectId).click();await other.getByTestId('open-video-'+videoId).click();await ready(other,0);await other.locator('.person').filter({hasText:'Track 1'}).click();await other.getByLabel('Go to frame').fill('10');await ready(other,10);await expect(other.locator('.gap-banner')).toContainText('Interpolation paused');
  await other.locator('.gap-banner').getByRole('button',{name:'Restore deleted range',exact:true}).click();await other.getByLabel('First frame to restore').fill('8');await other.getByLabel('Last frame to restore').fill('12');expect(requested).toBe(false);await other.getByRole('radio',{name:/Recover deleted boxes/}).check();await expect.poll(()=>requested).toBe(true);await expect(other.getByRole('button',{name:'Recover deleted boxes',exact:true})).toBeDisabled();await expect(other.locator('.restore-preview')).toHaveCount(0);await expect(other.getByRole('dialog')).toContainText('Loading saved edit history');expect((await state(request)).state).toEqual(blocked);releaseHistory();await expect(other.getByRole('dialog')).toContainText('3 boxes to restore');await other.getByRole('button',{name:'Recover deleted boxes',exact:true}).click();await saved(other);
  const recovered=await state(request);expect(at(recovered,10).boxes?.['class:person_visible']).toEqual(at({state:original},10).boxes?.['class:person_visible']);expect(at(recovered,8)).toEqual(at({state:blocked},8));expect(at(recovered,12)).toEqual(at({state:blocked},12));expect(Object.values(recovered.state.intervals)).toHaveLength(0);
  await other.getByTestId('canvas').press('Control+z');await saved(other);expect((await state(request)).state).toEqual(blocked);await other.getByTestId('canvas').press('Control+Shift+z');await saved(other);await reopen(other);await ready(other,10);expect((await state(request)).state).toEqual(recovered.state);
 }finally{releaseHistory();await fresh.close();}
});

