 await page.getByRole('menuitem',{name:'Change ID or class… I',exact:true}).click();await expect(page.getByLabel('Track ID',{exact:true})).toHaveValue('1');await expect(page.getByRole('button',{name:'Box color #ff0000',exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'Box color #ffffff',exact:true})).toHaveCount(0);await page.keyboard.press('Escape');
