 await clickSource(150,190,'right');await page.getByRole('menuitem',{name:'Delete box on this frame Delete',exact:true}).click();await saved(page);let p=await state(request);const first:any=Object.values(p.state.identities).find((i:any)=>i.person_id===1),row=obs(p).find(o=>o.identity_uuid===first.id);expect(row.boxes['class:person_extended']).toBeUndefined();expect(row.boxes['class:person_visible']).toBeDefined();await expect(page.getByRole('menu')).toHaveCount(0);await canvas.press('Control+z');await expect.poll(async()=>(await state(request)).state).toEqual(copied);await saved(page);
 const tools=page.getByRole('toolbar',{name:'Canvas tools',exact:true});await expect(canvas.getByRole('toolbar')).toHaveCount(0);
 await tools.getByRole('button',{name:'Hand tool (H)',exact:true}).click();await expect(canvas).toHaveAttribute('data-tool','hand');const x=await canvas.getAttribute('data-offset-x');await drag(page,[150,190],[170,195]);expect(await canvas.getAttribute('data-offset-x')).not.toBe(x);expect((await state(request)).state).toEqual(copied);
 await tools.getByRole('button',{name:'Select and move (V)',exact:true}).click();await expect(canvas).toHaveAttribute('data-tool','select');await clickSource(400,190);await expect(page.getByRole('button',{name:'Select Track 2',exact:true})).toHaveAttribute('aria-pressed','true');expect((await state(request)).state).toEqual(copied);
 await tools.getByRole('button',{name:'Draw box (B)',exact:true}).click();await expect(canvas).toHaveAttribute('data-tool','draw');await drag(page,[340,70],[460,310]);await saved(page);p=await state(request);const second:any=Object.values(p.state.identities).find((i:any)=>i.person_id===2);expect(obs(p).find(o=>o.identity_uuid===second.id).boxes['class:person_visible'][0]).toBeCloseTo(340,0);
 const scale=Number(await canvas.getAttribute('data-scale'));await tools.getByRole('button',{name:'Zoom in',exact:true}).click();await expect.poll(async()=>Number(await canvas.getAttribute('data-scale'))).toBeGreaterThan(scale);const zoomed=Number(await canvas.getAttribute('data-scale'));await tools.getByRole('button',{name:'Zoom out',exact:true}).click();await expect.poll(async()=>Number(await canvas.getAttribute('data-scale'))).toBeLessThan(zoomed);
 await tools.getByRole('button',{name:'Fit video',exact:true}).click();const fitted=await canvas.evaluate(element=>({width:element.clientWidth,height:element.clientHeight,x:Number(element.getAttribute('data-offset-x')),y:Number(element.getAttribute('data-offset-y')),scale:Number(element.getAttribute('data-scale'))}));expect(fitted.x).toBeCloseTo((fitted.width-p.videos[videoId].width*fitted.scale)/2,0);expect(fitted.y).toBeCloseTo((fitted.height-p.videos[videoId].height*fitted.scale)/2,0);expect((await state(request)).state).toEqual(p.state);
 for(const [key,tool] of [['h','hand'],['b','draw'],['v','select']]){await canvas.press(key);await expect(canvas).toHaveAttribute('data-tool',tool)}
