test('context copy-previous is disabled on an existing class box and does not replace corrections',async({page,request})=>{
 const canvas=page.getByTestId('canvas');await canvas.press('n');await drag(page,[100,80],[200,300]);await page.getByLabel('Go to frame').fill('10');await ready(page,10);await drag(page,[200,80],[300,300]);await page.getByLabel('Go to frame').fill('5');await ready(page,5);await drag(page,[200,190],[210,190]);await saved(page);const before=(await state(request)).state;
 const v=await canvas.evaluate(e=>{const r=e.getBoundingClientRect();return{x:r.x+Number(e.getAttribute('data-offset-x')),y:r.y+Number(e.getAttribute('data-offset-y')),s:Number(e.getAttribute('data-scale'))}});await page.mouse.click(v.x+205*v.s,v.y+190*v.s,{button:'right'});await expect(page.getByRole('menuitem',{name:'Copy previous box C',exact:true})).toBeDisabled();
 // Keep Radix's real closing menu mounted so the CI timing regression is deterministic.
 const exitStyle=await page.addStyleTag({content:'@keyframes regression-menu-close { from { opacity: 1; } to { opacity: 0; } } .canvas-context-menu[data-state="closed"] { animation: regression-menu-close 30s linear !important; }'});
 await expect.poll(()=>page.evaluate(()=>document.activeElement?.closest('[role="menu"]')?.getAttribute('data-state'))).toBe('open');
 await page.keyboard.press('Escape');await expect(page.locator('[role="menu"][data-state="closed"]')).toHaveCount(1);expect((await state(request)).state).toEqual(before);
 expect(await page.evaluate(()=>document.activeElement?.closest('[role="menu"]')?.getAttribute('data-state'))).toBe('closed');
 await page.keyboard.press('Delete');await expect.poll(async()=>!!at(await state(request),5)?.boxes?.['class:person_visible']).toBe(false);await saved(page);const deleted=(await state(request)).state;
 await page.keyboard.press('h');await expect(canvas).toHaveAttribute('data-tool','hand');await page.keyboard.press('v');await expect(canvas).toHaveAttribute('data-tool','select');
 await exitStyle.evaluate(element=>element.remove());await expect(page.getByRole('menu')).toHaveCount(0);
 await page.mouse.click(v.x+205*v.s,v.y+190*v.s,{button:'right'});await expect(page.getByRole('menuitem',{name:'Copy previous box C',exact:true})).toBeEnabled();await page.getByRole('menuitem',{name:'Copy previous box C',exact:true}).click();await saved(page);expect(at(await state(request),5).boxes['class:person_visible']).toEqual(at({state:before},4).boxes['class:person_visible']);await canvas.press('Control+z');await saved(page);expect((await state(request)).state).toEqual(deleted);await canvas.press('Control+z');await saved(page);expect((await state(request)).state).toEqual(before);
});

test('collision-shifted class badges select their exact box and share safe context actions',async({page,request})=>{
 const canvas=page.getByTestId('canvas');await canvas.press('n');await drag(page,[120,100],[220,300]);await copyTo(page,'person_extended');await saved(page);
 await canvas.press('n');await page.getByRole('button',{name:'Select class person_visible',exact:true}).click();await drag(page,[120,100],[220,300]);await saved(page);
 const before=await state(request),first:any=Object.values(before.state.identities).find((identity:any)=>identity.person_id===1),second:any=Object.values(before.state.identities).find((identity:any)=>identity.person_id===2);
 type Badge={x:number;y:number;width:number;height:number;identity:string;geometry:string;className:string};
 const badges=async()=>JSON.parse((await canvas.getAttribute('data-labels'))||'[]') as Badge[];
 const target=async()=>{const label=(await badges()).find(badge=>badge.identity===first.id&&badge.geometry==='class:person_extended');expect(label).toBeDefined();return label!};
 const clickBadge=async(button:'left'|'right')=>{const label=await target(),host=(await canvas.boundingBox())!;await page.mouse.click(host.x+label.x+label.width/2,host.y+label.y+label.height/2,{button});};
 await expect.poll(async()=>(await badges()).length).toBe(3);
 const label=await target(),painted=await badges(),view=await canvas.evaluate(element=>({x:Number(element.getAttribute('data-offset-x')),y:Number(element.getAttribute('data-offset-y')),scale:Number(element.getAttribute('data-scale'))}));
 expect(label.className).toBe('person_extended');expect(Math.max(Math.abs(label.x-(view.x+120*view.scale)),Math.abs(label.y-(view.y+100*view.scale-label.height-7)))).toBeGreaterThan(2);
 for(const other of painted.filter(badge=>badge.identity!==first.id||badge.geometry!=='class:person_extended')){
  expect(label.x+label.width<=other.x||other.x+other.width<=label.x||label.y+label.height<=other.y||other.y+other.height<=label.y).toBe(true);
 }
 // A normal badge click, even in draw mode with the wrong track active, selects without drawing.
 await page.getByRole('button',{name:'Draw box (B)',exact:true}).click();await clickBadge('left');await expect(page.getByRole('button',{name:'Select Track 1',exact:true})).toHaveAttribute('aria-pressed','true');await expect(page.getByRole('button',{name:'Select class person_extended',exact:true})).toHaveAttribute('aria-pressed','true');await saved(page);expect((await state(request)).state).toEqual(before.state);expect((await state(request)).revision).toBe(before.revision);
 await page.getByRole('button',{name:'Select Track 2',exact:true}).click();await page.getByRole('button',{name:'Select class person_visible',exact:true}).click();await clickBadge('right');
 const menu=page.getByRole('menu');await expect(menu).toContainText('Track 1 · person_extended');const badgeActions=await menu.getByRole('menuitem').allTextContents();await page.keyboard.press('Escape');
 // The class/ID badge and the selected underlying box expose the same menu.
 const host=(await canvas.boundingBox())!;await page.mouse.click(host.x+view.x+170*view.scale,host.y+view.y+200*view.scale,{button:'right'});await expect(menu).toContainText('Track 1 · person_extended');expect(await menu.getByRole('menuitem').allTextContents()).toEqual(badgeActions);await page.keyboard.press('Escape');
 await page.getByRole('button',{name:'Select Track 2',exact:true}).click();await page.getByRole('button',{name:'Select class person_visible',exact:true}).click();await clickBadge('right');await menu.getByRole('menuitem',{name:'Change ID or class… I',exact:true}).click();await expect(page.getByLabel('Track ID',{exact:true})).toHaveValue('1');await expect(page.getByLabel('Class name',{exact:true})).toHaveValue('person_extended');await page.keyboard.press('Escape');expect((await state(request)).state).toEqual(before.state);
 await page.getByRole('button',{name:'Select Track 2',exact:true}).click();await page.getByRole('button',{name:'Select class person_visible',exact:true}).click();await clickBadge('right');await menu.getByRole('menuitem',{name:'Delete box on this frame Delete',exact:true}).click();await saved(page);
 const after=await state(request),firstRow=obs(after).find(row=>row.identity_uuid===first.id);expect(firstRow.boxes['class:person_extended']).toBeUndefined();expect(firstRow.boxes['class:person_visible']).toEqual(obs(before).find(row=>row.identity_uuid===first.id).boxes['class:person_visible']);expect(obs(after).find(row=>row.identity_uuid===second.id)).toEqual(obs(before).find(row=>row.identity_uuid===second.id));
 await canvas.press('Control+z');await saved(page);expect((await state(request)).state).toEqual(before.state);
});
